INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('S-2026-10-07-CL51-FIXTURE-OWNERSHIP-V003','CL-51 full 86-light fixture register across two DiceBox flag formats','verification','Central Lodge CL-51','Foundry 14.367 Playwright no-write metadata and fixture sample','active','work/foundry-playwright-harness/receipts/cl51-fixture-register-v003.json','2026-10-07','86 unique canonical light stable IDs, 68 explicit owners and 18 inferred tunnel namespace placeholders','Corrects initial lightweight world.dicebox-only misclassification. 54 dicebox-campaign-helper namespace, 32 world.dicebox namespace. 28 event day/night, 26 local/power, 14 F1/F2 encounter, 18 explicitly inactive tunnel placeholders; all 86 hidden. Tunnel placeholders have canonical IDs and inactive state but no explicit managed-owner flag. No lighting changed.'),
('S-2026-10-07-CL91-STATEPATH-DEFECT-AUDIT','CL-91 progression ledger read-only writer and canonical path inspection','verification','Central Lodge CL-91 preparation','Foundry read-only journal, 115 RegionBehaviors, 132 world macros, kernel path contract','active','work/foundry-playwright-harness/cl91-n3-t3-branch-writer-audit-v001.page.js; cl91-global-branch-macro-scan-v001.page.js; cl91-ledger-statepath-schema-check-v001.page.js','2026-10-07','62 statePath assignments, 61 unique, 6 aliases absent from ledger schema before safe slice','N3 t3BranchUnlocked=false has zero literal mentions across all Lodge behaviors, shared kernel and 132 world macros. B1 underworksUnlocked, M3 serviceRouteUnlocked missing direct statePaths, likely deferred routes not automatic evidence of runtime defect. Six M1/M2/U2 original statePaths absent ledger, with old M1 clock compartment requiring noncanonical clockSettingSolved. Distinguish real alias corrections from unresolved authored gates.'),
('S-2026-10-07-CL91-M1-M2-ALIAS-REPAIR','CL-91 early safe-slice M1/M2 canonical ledger path repair','verification','Central Lodge CL-91 preparatory repair','Read-only exact source-hash PREVIEW, guarded in-place APPLY, independent no-write FINAL VERIFY','active','work/foundry-playwright-harness/cl91-m1-m2-statepath-preview-v001.page.js; cl91-m1-m2-alias-apply-v001.page.js; cl91-m1-m2-alias-final-verify-v001.page.js','2026-10-07','6 exact behavior source hashes verified; 21/202/115/33 ledger rev0','M1 clock emblem now writes silverFamilyEmblemInstalled; two compartment scripts read clockSettingResolved; M2 portrait glass eye writes glassEyeInstalled, piano writes pianoRollInstalled, reliquary writes reliquaryUnlocked. Kernel, global counts and ledger unchanged. M1 clock setting writer still absent; M2 founderPortraitOpened and U2 servantHistoryObserved aliases not touched. No gameplay canary.');

INSERT OR REPLACE INTO kb_facts(fact_id,domain,subject_no,title,statement,scope,evidence_class,status,source_id,supersedes_fact_id,tags) VALUES
('F-2026-10-07-CL51-FIXTURE-OWNERSHIP-V003','campaign.central-lodge.lighting',NULL,'CL-51 lighting metadata reconciled across two flag formats','All 86 ambient fixtures retain 86 unique canonical light stable IDs and are hidden. 54 fixtures carry dicebox-campaign-helper flags and 32 carry world.dicebox flags. 68 explicitly declare managed owner and 18 tunnel placeholders have inferred DiceBox ownership from canonical IDs but no explicit owner tag; they are purposely inactive. 28 lights are controlled by planned event-driven day/night; 26 by local/power states; 14 by F1/F2 ritual state; 18 are inactive tunnel placeholders. Original assertion that only 14 fixtures were managed was an artifact of a one-namespace-only read. Night trigger undecided; 0 light writes.','campaign','static','locked','S-2026-10-07-CL51-FIXTURE-OWNERSHIP-V003','F-2026-10-07-CL51-LIGHT-INVENTORY','central lodge cl51 86 fixtures two namespaces 68 explicit 18 inferred'),
('F-2026-10-07-CL91-BRANCH-NO-WRITER','campaign.central-lodge.qa',NULL,'N3 to T3 branch unlock currently has no live DiceBox writer','The canonical ledger contains puzzles.n3.t3BranchUnlocked=false. A separate read-only scan of all 115 Lodge RegionBehaviors, the shared runtime kernel, and all 132 world macros found ZERO literal references to t3BranchUnlocked. N3 Branch Railway Region has no behavior. T3 to F1 and T3 to N3 exits exist; N3 to T3 progression unlock remains unimplemented in audited code. Do not fabricate switch/overlay prerequisite policy or set the flag without authored approval.','campaign','static','locked','S-2026-10-07-CL91-STATEPATH-DEFECT-AUDIT',NULL,'central lodge cl91 n3 t3BranchUnlocked orphan missing unlock writer'),
('F-2026-10-07-CL91-M1-M2-ALIAS-REPAIR','campaign.central-lodge.qa',NULL,'Six canonical ledger path alias corrections independently verified','A no-write PREVIEW found six M1/M2 RegionBehavior script paths naming flags absent from canonical ledger schema. Guarded in-place APPLY PASS and independent read-only FINAL VERIFY PASS: M1 emblem insert writes puzzles.m1.silverFamilyEmblemInstalled, two clock compartment pickups check puzzles.m1.clockSettingResolved; M2 portrait, piano and reliquary write puzzles.m2.glassEyeInstalled, puzzles.m2.pianoRollInstalled and puzzles.m2.reliquaryUnlocked. Six source hashes verified. 21/202/115/33, ledger revision 0, no gameplay canary. The actual M1 clock-setting action/writer is still missing and two other noncanonical paths deferred.','campaign','full_function','locked','S-2026-10-07-CL91-M1-M2-ALIAS-REPAIR',NULL,'central lodge cl91 six alias repairs independent final verify');
