INSERT OR REPLACE INTO kb_decisions(decision_id,topic,decision,rationale,scope,status,owner,source_id,next_review) VALUES
('D-456','CL-51 fixture authority uses both DiceBox metadata namespaces','Read both dicebox-campaign-helper and world.dicebox light flags. Classify 68 explicitly owner-labeled fixtures separately from 18 canonical-but-owner-inferred inactive tunnel placeholders. Preserve current hidden state and require user-named story event for global night; never bulk-enable by naive namespace-only ownership.','Prior metadata audit saw only 14 world.dicebox managed lights because the 54 fixtures in legacy namespace were overlooked and 18 tunnel placeholders have incomplete owner metadata.','campaign','locked','Foreman','S-2026-10-07-CL51-FIXTURE-OWNERSHIP-V003',NULL),
('D-457','CL-91 canonical alias repair scope limited to exact M1/M2 paths','Patch only the six code paths directly mismatching a semantically corresponding canonical ledger flag; preserve all other source logic, events and ledger. Do not fabricate clock puzzle setting, N3 branch unlock, U2 history interpretation or Founder Portrait stage; they remain governed open work.','Foundry read-only PREVIEW and frozen original/new source hashes demonstrate exact alias match; separate FINAL VERIFY ensures no other changes.','campaign','locked','Foreman','S-2026-10-07-CL91-M1-M2-ALIAS-REPAIR',NULL);
